using System;namespace KeyJaya {public static class SelectionAnchorTests {
 public static int Main(){int passed=0;foreach(string prefix in new[]{"","Earlier untouched ","A\nB\t ","কৃষ্ণ रāja ",new string('x',200000)}){var anchor=new SelectionAnchor(prefix);if(!anchor.Matches(prefix)||anchor.Matches(prefix+" ")||anchor.Matches(null))throw new Exception("anchor scope");passed+=3;if(prefix.Length>0){string changed=(prefix[0]=='x'?"y":"x")+prefix.Substring(1);if(anchor.Matches(changed))throw new Exception("changed preceding text accepted");passed++;}}try{new SelectionAnchor(new string('x',200001));throw new Exception("unbounded anchor accepted");}catch(ArgumentException){passed++;}
 string expected="sañjaya uvāca\nfirst verse.\n\nsecond verse.\n\nthird verse.";
 foreach(string separator in new[]{"\n","\r\n","\r","\u2028","\u2029"})foreach(int count in new[]{1,2,3}){string observed=expected.Replace("\n\n","\n").Replace("\n",new string(separator[0],count));if(separator=="\r\n")observed=observed.Replace("\r","\r\n");if(!SelectionConversion.PastedTextMatches(expected,observed))throw new Exception("Browser paragraph representation rejected");passed++;}
 foreach(string changed in new[]{expected.Replace("second verse.\n\n",""),expected.Replace("first verse.","first  verse."),expected.Replace("sañjaya","sanjaya"),expected.Replace("second verse.","wrong verse."),expected.Replace("second verse.\n\nthird verse.","third verse.\n\nsecond verse."),expected+" next",expected.Replace("verse.","verse!"),"\n"+expected}){if(SelectionConversion.PastedTextMatches(expected,changed))throw new Exception("Changed pasted content accepted");passed++;}
 if(SelectionConversion.PastedTextMatches(null,expected)||SelectionConversion.PastedTextMatches(expected,null)||SelectionConversion.PastedTextMatches("","")||SelectionConversion.PastedTextMatches(new string('a',200001),new string('a',200001)))throw new Exception("Unbounded or empty paste accepted");passed+=4;
 foreach(string ending in new[]{"","\n","\r\n","\u2029"})foreach(string gap in new[]{"","\r","\n","\u2028","\u2029"}){if(!SelectionConversion.PastedCaretMatches(expected,expected+ending,gap))throw new Exception("Logical end caret rejected because provider paragraph endpoints differ");passed++;}
 foreach(string preceding in new[]{expected+" next",expected.Replace("second verse.",""),"other "+expected,expected.Substring(0,expected.Length-1),"",null}){if(SelectionConversion.PastedCaretMatches(expected,preceding,""))throw new Exception("Wrong or incomplete output cannot claim caret");passed++;}
 foreach(string following in new[]{"next"," ",".",new string('\n',33),null}){if(SelectionConversion.PastedCaretMatches(expected,expected,following))throw new Exception("A caret inside or outside the verified output cannot claim its end");passed++;}
 Console.WriteLine("PASS: "+passed+" FAIL: 0");return 0;}
}}
